36	/** Helper to parse the JSON from a handoff result (accepts plain objects or Promises) */
37	async function parseResult(resultOrPromise: any): Promise<any> {
38	  const result = await resultOrPromise;
39	  return JSON.parse(result.content[0].text);
40	}
41	
42	// Fixed plan path used as LedgerStore project path; tempDir is used only as the ledgerRoot.
