44	const PLAN_PATH = join(tmpdir(), '2026-01-01-ledger-test');
45	
46	/** Build a minimal WP detail stub */
47	function makeWp(
48	  id: string,
49	  status: string,
50	  pipelines: Array<{ type: string; status: string }> = [],
51	  deps: string[] = [],
52	  assignedTo: string = 'Developer'
53	): WorkPackageDetail {
54	  return {
