 21	import {
 22	  buildHandoffPrompt,
 23	  isBlockedByDependencies,
 24	  isMostRecentPipelineFail,
 25	  latestNonCancelledPipeline,
 26	  effectiveMaxDepth,
 27	  hasDownstreamReengagedSince,
 28	  hasNewUpstreamPassSince,
 29	} from '../utils/workflow-helpers.js';
 30	import { getConfig } from '../gui/config.js';
 31	import { isTerminalStatus } from '../schema/validators.js';
 32	
 33	/** Shared return type for all per-role handoff handlers. */
 34	type HandoffResult = { content: Array<{ type: string; text: string }>; isError?: boolean };
 35	
 36	/** Handler signature: (wpDetails, projectPath, store) → handoff result. */
 37	type HandoffHandler = (
 38	  wpDetails: WorkPackageDetail[],
 39	  projectPath?: string,
 40	  store?: LedgerStore,
 41	) => Promise<HandoffResult>;
 42	
 43	/**
 44	 * Manifest-typed dispatch map from agent role → handoff handler.
 45	 *
 46	 * Keyed by `AgentRole` (derived from the shared workflow manifest) so that
 47	 * TypeScript flags any mismatch when a role is added, removed, or renamed.
 48	 * This replaces the two former switch statements in `getHandoffStatus()` and
 49	 * `computeHandoffStatus()` with a single source of truth.
 50	 */
 51	const HANDOFF_DISPATCH: Record<AgentRole, HandoffHandler> = {
 52	  'Planner':          getPlannerHandoff,
 53	  'Project Manager':  getProjectManagerHandoff,
 54	  'Developer':        getDeveloperHandoff,
 55	  'QA':               getQaHandoff,
 56	  'Security Auditor': getSecurityAuditorHandoff,
 57	  'Reviewer':         getReviewerHandoff,
 58	  'Release Engineer': getReleaseEngineerHandoff,
 59	  'Documentation':    getDocumentationHandoff,
 60	  'Synthesis':        (_, projectPath, store) =>
 61	    buildHandoffResponse(
 62	      'Synthesis',
 63	      'COMPLETE',
 64	      'Synthesis complete.',
 65	      'Call ledger_get_next_action first to check if synthesis work is pending before generating your report.',
 66	      projectPath,
 67	      store,
 68	    ),
 69	};
 70	
 71	/**
 72	 * Tool: get_handoff_status
 73	 *
 74	 * Reads root index and examines all WP statuses and pipelines to compute
 75	 * the correct AGENT: and STATUS: handoff block for the current agent.
 76	 */
 77	const GetHandoffStatusSchema = z.object({
 78	  project_path: z.string().optional().describe('Absolute path to the plan folder. Use this if you already have it from a previous tool response or if it was provided in your instructions. Takes precedence over cwd_path if both are given.'),
 79	  cwd_path: z.string().optional().describe('Your current workspace root directory. The server auto-detects the active project. Ignored if project_path is also provided.'),
 80	  current_agent: z
 81	    .string()
 82	    .describe(
 83	      'REQUIRED. Your agent role, exactly one of: "Planner", "Project Manager", "Developer", "QA", "Security Auditor", "Reviewer", "Release Engineer", "Documentation", "Synthesis"'
 84	    ),
 85	});
 86	
 87	async function getHandoffStatus(args: z.infer<typeof GetHandoffStatusSchema>) {
 88	  let projectPath: string;
 89	  try {
 90	    projectPath = await resolveProjectPath(args);
 91	  } catch (err) {
 92	    return { content: [{ type: 'text' as const, text: `Error: ${(err as Error).message}` }], isError: true };
 93	  }
 94	
 95	  const store = new LedgerStore(projectPath);
 96	
 97	  try {
 98	    // Validate agent role
 99	    if (!AGENT_ROLES.includes(args.current_agent as AgentRole)) {
100	      throw new Error(

101	        `Unknown agent role: ${args.current_agent}. Valid roles are: ${AGENT_ROLES.join(', ')}`
102	      );
103	    }
104	
105	    // Read root index
106	    const rootIndex = await store.readRootIndex();
107	
108	    // Check for BLOCKED work packages. Report BLOCKED whenever blocked WPs exist
109	    // and nothing is actionable (no READY or IN_PROGRESS WPs), regardless of
110	    // whether some WPs are already COMPLETE. A mixed BLOCKED + COMPLETE state
111	    // with no forward progress indicates a genuine stall that needs PM resolution.
112	    const blockedWps = rootIndex.work_packages.filter(
113	      (wp) => wp.status === 'BLOCKED'
114	    );
115	    const readyOrInProgressWps = rootIndex.work_packages.filter(
116	      (wp) => wp.status === 'READY' || wp.status === 'IN_PROGRESS'
117	    );
118	
119	    if (blockedWps.length > 0 && readyOrInProgressWps.length === 0) {
120	      return buildHandoffResponse(
121	        args.current_agent,
122	        'BLOCKED',
123	        `All work packages are BLOCKED: ${blockedWps.map((wp) => wp.work_package_id).join(', ')}. Resolution required before proceeding.`,
124	        undefined,
125	        projectPath,
126	        store
127	      );
128	    }
129	
130	    // Load all WP details to examine pipeline states first
131	    // (We need this to make informed decisions about handoff status)
132	    const wpDetails = await Promise.all(
133	      rootIndex.work_packages.map((wp) =>
134	        store.readWorkPackage(wp.work_package_id)
135	      )
136	    );
137	
138	    // Agent-specific handoff logic (dispatch map is typed by AgentRole from the manifest)
139	    const handler = HANDOFF_DISPATCH[args.current_agent as AgentRole];
140	    if (handler) {
141	      return handler(wpDetails, projectPath, store);
142	    }
143	    return buildHandoffResponse(args.current_agent, 'IN_PROGRESS', 'Work in progress.', undefined, projectPath, store);
144	  } catch (error) {
145	    return {
146	      content: [
147	        {
148	          type: 'text' as const,
149	          text: `Error: ${(error as Error).message}`,
150	        },
151	      ],
152	      isError: true,
153	    };
154	  }
155	}
156	
157	/**
158	 * Derive the next agent from a handoff status.
159	 *
160	 * For READY_FOR_* statuses the next agent is the target role.
161	 * For IN_PROGRESS the caller continues (next === current).
162	 * For BLOCKED, the Project Manager triages.
163	 * For COMPLETE, no next agent is needed.
164	 */
165	export function nextAgentFromStatus(status: string, currentAgent: string): string | null {
166	  if (status === 'IN_PROGRESS') return currentAgent;
167	  if (isTerminalStatus(status)) return null;
168	  return HANDOFF_STATUS_ROLE[status] ?? null;
169	}
170	
171	/** Build a standard handoff response payload with current_agent, next_agent, and status.
172	 *
173	 * When `projectPath` and `store` are provided, this function will also attempt to include
174	 * an `auto_handoff` object in the payload if all eligibility conditions are met:
175	 * - Registry is loaded (`isRegistryLoaded()` returns true)
176	 * - Next agent has a known VS Code handle
177	 * - Status is not COMPLETE, BLOCKED, or IN_PROGRESS
178	 * - `auto_handoff_depth` in the ledger is below `effectiveMaxDepth(total_work_packages)` (§18.2.1)
179	 *
180	 * The depth counter is reset to 0 only inside completeSynthesis (§18.4), not on individual WP completions.
181	 */
182	export async function buildHandoffResponse(
183	  currentAgent: string,
184	  status: string,
185	  details: string,
186	  nextAction?: string,
187	  projectPath?: string,
188	  store?: LedgerStore
189	) {
190	  const nextAgent = nextAgentFromStatus(status, currentAgent);
191	  const payload: Record<string, unknown> = {
192	    current_agent: currentAgent,
193	    ...(nextAgent ? { next_agent: nextAgent } : {}),
194	    status,
195	    details,
196	  };
197	  if (nextAction) payload.next_action = nextAction;
198	
199	  // Auto-handoff eligibility check.
200	  // NOTE: `status` here is the handoff status value (e.g., READY_FOR_DEVELOPER, READY_FOR_PM),
201	  // NOT the ProjectStatus (e.g., IN_PROGRESS). Auto-handoff triggers only for
202	  // READY_FOR_* statuses — non-READY_FOR_* values (COMPLETE, BLOCKED, IN_PROGRESS, WAIT)
203	  // are explicitly excluded by the conditions below.
204	  if (
205	    projectPath &&
206	    store &&
207	    status !== 'COMPLETE' &&
208	    status !== 'BLOCKED' &&
209	    status !== 'IN_PROGRESS' &&
210	    getConfig().auto_handoff_enabled &&
211	    isRegistryLoaded()
212	  ) {
213	    const agentName = nextAgent ? getAgentHandle(nextAgent) : null;
214	    if (agentName !== null) {
215	      try {
216	        const root = await store.readRootIndex();
217	        const currentDepth = root.auto_handoff_depth ?? 0;
218	        if (currentDepth < effectiveMaxDepth(root.total_work_packages ?? 0)) {
219	          await store.writeRootIndex({
220	            ...root,
221	            auto_handoff_depth: currentDepth + 1,
222	            last_updated: now(),
223	          });
224	          const agentId = nextAgent ? getAgentId(nextAgent) : null;
225	          const agentNames = nextAgent ? AGENT_NAMES[nextAgent as AgentRole] : null;
226	          payload.auto_handoff = {
227	            agent_name: agentName,
228	            ...(agentId !== null ? { agent_id: agentId } : {}),
229	            ...(agentNames ? {
230	              cc_agent_name: agentNames.claude_code.agent_name,
231	              vs_agent_name: agentNames.vscode.agent_name,
