322	/**
323	 * Returns true if the WP has a PASS pipeline of the prerequisite stage for `currentStage`,
324	 * given its active_pipeline_stages. When the prerequisite resolves to null (currentStage
325	 * is the first active stage), the prerequisite is vacuously satisfied (returns true).
326	 *
327	 * Mirrors the `hasPassedEffectiveUpstream` pattern already used in getDocumentationHandoff.
328	 */
329	function hasPassedDynamicUpstream(
330	  wp: WorkPackageDetail,
331	  currentStage: PipelineType,
332	): boolean {
333	  const activeStages =
334	    (wp.active_pipeline_stages as PipelineType[] | undefined) ?? DEFAULT_PIPELINE_STAGES;
335	  const upstream = resolvePrerequisite(currentStage, activeStages);
336	  if (upstream === null) return true;
