340	/**
341	 * Given a list of WPs that have PASSed `currentStage`, returns the WPs whose
342	 * resolved next stage has not yet started, partitioned into ready and dependency-blocked.
343	 * Also returns the canonical READY_FOR_* status to emit.
344	 *
345	 * Mixed-routing safety rule (audit 2026-04-29): if the `ready` set contains WPs
346	 * routing to two or more distinct next agents (e.g., a project mixing
347	 * `[..., code-review, documentation]` with `[..., code-review, release-engineering, documentation]`),
348	 * `nextStatus` is returned as `null` so the caller falls through to WAIT. The
349	 * orchestrator's per-agent `ledger_get_next_action` ticks then dispatch each WP
350	 * individually. Emitting a single `next_agent` for a heterogeneous set would
351	 * misroute the WPs that don't match.
352	 *
353	 * Last-stage edge case: when `currentStage` is the last active stage for a WP,
354	 * `resolveNextAgent` returns 'Synthesis' and `AGENT_PIPELINE_MAP['Synthesis']`
355	 * is undefined (Synthesis owns no pipeline). Such WPs are skipped here — they
356	 * are handled by the all-terminal early exit once every WP reaches a terminal
357	 * status. Partial completion falls through to WAIT, which is the correct
358	 * spec-mandated behavior.
359	 */
360	function partitionWpsAwaitingNextStage(
361	  wpsPassedCurrent: WorkPackageDetail[],
362	  currentStage: PipelineType,
363	): {
364	  ready: WorkPackageDetail[];
365	  blocked: WorkPackageDetail[];
366	  nextStatus: string | null;
367	} {
368	  const awaiting = wpsPassedCurrent.filter((wp) => {
369	    const activeStages =
370	      (wp.active_pipeline_stages as PipelineType[] | undefined) ?? DEFAULT_PIPELINE_STAGES;
371	    const nextAgent = resolveNextAgent(currentStage, activeStages);
372	    const nextStage = AGENT_PIPELINE_MAP[nextAgent as AgentRole];
373	    // No next stage (currentStage is the last active stage) → routes to Synthesis,
374	    // handled separately by the all-terminal check.
375	    if (!nextStage) return false;
376	    // "Next stage not started" means no PASS pipeline exists for the next stage.
377	    // A FAIL pipeline means the next stage was attempted but hasn't succeeded —
378	    // the upstream agent (current caller) still needs to route there.
379	    return !wp.pipelines.some((p) => p.type === nextStage && p.status === 'PASS');
380	  });
381	  const ready = awaiting.filter((wp) => !isBlockedByDependencies(wp));
382	  const blocked = awaiting.filter((wp) => isBlockedByDependencies(wp));
383	
384	  // Mixed-routing guard: collect the set of distinct next agents across all ready WPs.
385	  const nextAgents = new Set(
386	    ready.map((wp) => {
387	      const activeStages =
388	        (wp.active_pipeline_stages as PipelineType[] | undefined) ?? DEFAULT_PIPELINE_STAGES;
389	      return resolveNextAgent(currentStage, activeStages);
390	    }),
391	  );
392	
393	  // Only emit a single READY_FOR_* status when ALL ready WPs route to the same next agent.
394	  // If the set is heterogeneous, return null → caller falls through to WAIT.
395	  const nextStatus =
396	    nextAgents.size === 1
397	      ? (READY_STATUS_FOR_ROLE[[...nextAgents][0] as AgentRole] ?? null)
398	      : null;
399	
400	  return { ready, blocked, nextStatus };
401	}
