446	    const status = READY_STATUS_FOR_ROLE[targetRole as AgentRole] ?? 'READY_FOR_DEVELOPER';
447	    return {
448	      status,
449	      reason: `${wp.work_package_id} is READY; routing to ${targetRole} for ${stage} stage. (Cross-WP dispatch from ${currentRole}.)`,
450	    };

