1273	/**
1274	 * Get handoff status for Documentation (§5.4)
1275	 *
1276	 * Priority order per §14.5: ready-for-docs (new work or re-engagement via
1277	 * hasNewUpstreamPassSince) comes BEFORE FAIL self-rework. This is the opposite
1278	 * of the recommendation engine priority and is intentional for handoff routing.
1279	 */
1280	export async function getDocumentationHandoff(wpDetails: WorkPackageDetail[], projectPath?: string, store?: LedgerStore) {
1281	  // All-terminal early exit (§5.4): applies to all WPs regardless of active stages.
1282	  if (wpDetails.every((wp) => isTerminalStatus(wp.status))) {
1283	    return buildHandoffResponse(
1284	      'Documentation',
1285	      'READY_FOR_SYNTHESIS',
1286	      'All work packages are terminal.',
1287	      undefined,
1288	      projectPath,
1289	      store
1290	    );
1291	  }
1292	
1293	  // Scope filter (§13.1): only WPs that include 'documentation' in their active stages
1294	  // are subject to pipeline-specific checks. Legacy WPs fall back to DEFAULT_PIPELINE_STAGES.
1295	  const docWps = scopeToStage(wpDetails, 'documentation');
1296	
1297	  // Step 1 of §5.4 (Condition 1): Ready-for-docs check — new documentation OR re-engagement.
1298	  // Per §14.5: this step comes BEFORE FAIL self-rework in handoff priority.
1299	  // Uses hasPassedDynamicUpstream for upstream PASS detection and hasNewUpstreamPassSince
1300	  // for re-engagement (a new upstream PASS after the most recent documentation run).
1301	  // Documentation-only WPs (null upstream) match only via "no documentation pipeline yet".
1302	  const readyForDocsList = docWps.filter((wp) => {
1303	    if (isTerminalStatus(wp.status) || isBlockedByDependencies(wp)) return false;
1304	    if (!hasPassedDynamicUpstream(wp, 'documentation')) return false;
1305	    // No documentation pipeline yet → ready for docs
1306	    if (!wp.pipelines.some((p) => p.type === 'documentation')) return true;
1307	    // Re-engagement: check if effective upstream has re-passed since last doc run.
1308	    // §14.6: hasNewUpstreamPassSince(null, "documentation") returns false,
1309	    // so documentation-only WPs only match via "no documentation pipeline yet" above.
1310	    const activeStages =
1311	      (wp.active_pipeline_stages as PipelineType[] | undefined) ?? DEFAULT_PIPELINE_STAGES;
1312	    const upstream = resolvePrerequisite('documentation', activeStages);
1313	    return upstream !== null && hasNewUpstreamPassSince(wp.pipelines, upstream, 'documentation');
1314	  });
1315	  if (readyForDocsList.length > 0) {
1316	    return buildHandoffResponse(
1317	      'Documentation',
1318	      'IN_PROGRESS',
1319	      `Documentation work in progress. ${readyForDocsList.length} work package(s) need documentation or re-documentation after upstream changes.`,
1320	      `Call ledger_get_next_action with agent_role: "Documentation" to find the next work package to document. Continue working until all WPs have PASS documentation pipelines and are marked COMPLETE.`,
1321	      projectPath,
1322	      store
1323	    );
1324	  }
1325	
1326	  // Step 2 of §5.4 (Condition 2): FAIL → Documentation self-rework.
1327	  // Documentation self-corrects on FAIL rather than routing back upstream.
1328	  // Note: no upstream-PASS gate here — the spec (§5.4) requires only non-terminal,
1329	  // non-dep-blocked, most-recent-doc-FAIL. If upstream has since re-passed (a new
1330	  // upstream PASS after the doc FAIL), the re-engagement path in Step 1 catches that
1331	  // case first (via readyForDocsList). So Condition 2 remains correct for all other
1332	  // upstream states, including when upstream has since regressed to FAIL (see R4.4b).
1333	  const wpsWithDocFail = docWps.filter(
1334	    (wp) =>
1335	      !isTerminalStatus(wp.status) &&
1336	      !isBlockedByDependencies(wp) &&
1337	      isMostRecentPipelineFail(wp.pipelines, 'documentation')
1338	  );
1339	  if (wpsWithDocFail.length > 0) {
1340	    return buildHandoffResponse(
1341	      'Documentation',
1342	      'IN_PROGRESS',
1343	      `Documentation rework required. ${wpsWithDocFail.length} work package(s) have FAIL documentation pipelines and need rework.`,
1344	      `Call ledger_get_next_action with agent_role: "Documentation" to find the next work package to document. Continue working until all WPs have PASS documentation pipelines and are marked COMPLETE.`,
1345	      projectPath,
1346	      store
1347	    );
1348	  }
1349	
1350	  // Step 3 of §5.4: WPs in earlier pipeline stages — per spec v2.0.0, Documentation
1351	  // cannot accurately dispatch to the correct upstream agent (Developer / QA / Reviewer etc.).
1352	  // Defer to orchestrator polling — fall through to WAIT.
1353	
1354	  // Step 4 of §5.4: Cross-WP dispatch — if a READY WP exists whose dependencies are
1355	  // satisfied, route to the agent owning its first active pipeline stage. Prevents IDE
1356	  // stall when Documentation's role-specific work is done but other WPs have not yet
1357	  // started any pipelines. Fallthrough to WAIT when no dispatch found.
1358	  const dispatch = findNextReadyDispatch(wpDetails, 'Documentation');
1359	  if (dispatch) {
1360	    return buildHandoffResponse(
1361	      'Documentation',
1362	      dispatch.status,
1363	      dispatch.reason,
1364	      undefined,
1365	      projectPath,
1366	      store
1367	    );
1368	  }
1369	
1370	  // Fallthrough (§5.4 Condition 5) → WAIT.
1371	  return buildHandoffResponse(
1372	    'Documentation',
1373	    'WAIT',
1374	    'No actionable documentation work.',
1375	    undefined,
1376	    projectPath,
1377	    store
1378	  );
1379	}
