1381	/**
1382	 * Compute the handoff status payload without wrapping in an MCP response.
1383	 *
1384	 * Shared utility called by workflow-next-action.ts to embed `handoff_status`
1385	 * directly in `WAIT` responses, eliminating the need for a separate
1386	 * `ledger_get_handoff_status` call by Developer, QA, and Reviewer agents.
1387	 *
1388	 * When `opts.store`, `opts.rootIndex`, and `opts.wpDetails` are ALL provided, the
1389	 * function bypasses `getHandoffStatus()` entirely — dispatching directly to the
1390	 * per-role handoff function with the pre-loaded data. This eliminates the redundant
1391	 * LedgerStore construction and disk reads that would otherwise occur on every
1392	 * WAIT response in the next-action flow.
1393	 *
1394	 * When any of the three opts fields is absent (or opts is omitted), the function
1395	 * falls back to calling `getHandoffStatus()` as before — preserving compatibility
1396	 * with the standalone `ledger_get_handoff_status` tool call path.
1397	 *
1398	 * @throws {Error} if handoff status computation fails (invalid path, project not found, etc.)
1399	 */
1400	export async function computeHandoffStatus(
1401	  projectPath: string,
1402	  agentRole: string,
1403	  opts?: { store?: LedgerStore; rootIndex?: RootIndex; wpDetails?: WorkPackageDetail[] },
1404	): Promise<Record<string, unknown>> {
1405	  // Fast path: all three pre-loaded values available — bypass getHandoffStatus()
1406	  if (opts?.store && opts?.rootIndex && opts?.wpDetails) {
1407	    const { store: s, rootIndex, wpDetails } = opts;
1408	    let mcpResult: { content: Array<{ type: string; text: string }> };
1409	
1410	    // Replicate the global BLOCKED short-circuit from getHandoffStatus
1411	    const blockedWps = rootIndex.work_packages.filter((wp) => wp.status === 'BLOCKED');
1412	    const readyOrInProgressWps = rootIndex.work_packages.filter(
1413	      (wp) => wp.status === 'READY' || wp.status === 'IN_PROGRESS'
1414	    );
1415	    if (blockedWps.length > 0 && readyOrInProgressWps.length === 0) {
1416	      mcpResult = await buildHandoffResponse(
1417	        agentRole,
1418	        'BLOCKED',
1419	        `All work packages are BLOCKED: ${blockedWps.map((wp) => wp.work_package_id).join(', ')}. Resolution required before proceeding.`,
1420	        undefined,
1421	        projectPath,
1422	        s
1423	      );
1424	    } else {
1425	      // Dispatch via manifest-typed map (same map used by getHandoffStatus)
1426	      const handler = HANDOFF_DISPATCH[agentRole as AgentRole];
1427	      if (handler) {
1428	        mcpResult = await handler(wpDetails, projectPath, s);
1429	      } else {
1430	        mcpResult = await buildHandoffResponse(agentRole, 'IN_PROGRESS', 'Work in progress.', undefined, projectPath, s);
1431	      }
1432	    }
1433	
1434	    if ('isError' in mcpResult && (mcpResult as { isError?: boolean }).isError) {
1435	      const errText = (mcpResult.content as Array<{ text: string }>)[0]?.text ?? 'Handoff status computation failed';
1436	      throw new Error(errText);
1437	    }
1438	    const fastText = (mcpResult.content as Array<{ type: string; text: string }>)[0]?.text ?? '{}';
1439	    return JSON.parse(fastText) as Record<string, unknown>;
1440	  }
1441	
1442	  // Fallback: original path — constructs a fresh LedgerStore via getHandoffStatus()
1443	  const mcpResult = await getHandoffStatus({ project_path: projectPath, current_agent: agentRole });
1444	  if ('isError' in mcpResult && mcpResult.isError) {
1445	    const errText = (mcpResult.content as Array<{ text: string }>)[0]?.text ?? 'Handoff status computation failed';
1446	    throw new Error(errText);
1447	  }
1448	  const text = (mcpResult.content as Array<{ type: string; text: string }>)[0]?.text ?? '{}';
1449	  return JSON.parse(text) as Record<string, unknown>;
1450	}

